#!/usr/bin/env bash
set -uo pipefail
ROOT="${RUN_ROOT:-/workspace/runs/g5-8gpu-strategy-research-20260829/vpp_strategy_controls_$(date -u +%Y%m%dT%H%M%SZ)}"; CODE="${CODE_DIR:-/workspace/code/Megatron-LM}"; mkdir -p "$ROOT"
export NCCL_P2P_DISABLE=1 NCCL_IB_DISABLE=1 NCCL_SOCKET_IFNAME=eth0 CUDA_DEVICE_MAX_CONNECTIONS=1 OMP_NUM_THREADS=8 CUDA_VISIBLE_DEVICES=0,1,2,3,4,5,6,7
BASE=(--num-layers 32 --hidden-size 1024 --ffn-hidden-size 3072 --num-attention-heads 16 --group-query-attention --num-query-groups 4 --seq-length 1024 --max-position-embeddings 4096 --micro-batch-size 1 --global-batch-size 8 --bf16 --use-mcore-models --use-distributed-optimizer --position-embedding-type rope --rotary-percent 1.0 --rotary-base 10000 --tokenizer-type NullTokenizer --vocab-size 32768 --normalization RMSNorm --norm-epsilon 1e-6 --swiglu --disable-bias-linear --untie-embeddings-and-output-weights --mock-data --train-iters 45 --eval-iters 0 --eval-interval 100000 --lr 1e-6 --min-lr 1e-7 --lr-decay-style constant --log-interval 1 --seed 20260829 --pipeline-schedule interleaved)
run_case(){ local n="$1"; shift; local o="$ROOT/$n"; mkdir -p "$o"; printf 'name=%s\n' "$n" > "$o/meta.txt"; timeout --signal=TERM --kill-after=45s 1200 python3 -m torch.distributed.run --standalone --nproc-per-node=8 "$CODE/pretrain_gpt.py" "${BASE[@]}" "$@" > "$o/train.log" 2>&1; local rc=$?; printf '%s\t%s\n' "$n" "$rc" >> "$ROOT/status.tsv"; grep -E 'elapsed time per iteration|throughput per GPU|memory \(MB\)|Traceback|RuntimeError|AssertionError|ValueError|unsupported|NCCL' "$o/train.log" | tail -120 > "$o/extract.txt" || true; grep 'elapsed time per iteration' "$o/train.log" | tail -20 > "$o/steady.tsv" || true; }
# PP4/TP2/VPP4 controls.
run_case pp4_vpp4_base --tensor-model-parallel-size 2 --pipeline-model-parallel-size 4 --num-layers-per-virtual-pipeline-stage 2 --microbatch-group-size-per-virtual-pipeline-stage 4
run_case pp4_vpp4_delay_wgrad --tensor-model-parallel-size 2 --pipeline-model-parallel-size 4 --num-layers-per-virtual-pipeline-stage 2 --microbatch-group-size-per-virtual-pipeline-stage 4 --delay-wgrad-compute
run_case pp4_vpp4_defer_embed_all --tensor-model-parallel-size 2 --pipeline-model-parallel-size 4 --num-layers-per-virtual-pipeline-stage 2 --microbatch-group-size-per-virtual-pipeline-stage 4 --defer-embedding-wgrad-compute
run_case pp4_vpp4_defer_embed_2 --tensor-model-parallel-size 2 --pipeline-model-parallel-size 4 --num-layers-per-virtual-pipeline-stage 2 --microbatch-group-size-per-virtual-pipeline-stage 4 --defer-embedding-wgrad-compute --wgrad-deferral-limit 2
run_case pp4_vpp4_nosg --tensor-model-parallel-size 2 --pipeline-model-parallel-size 4 --num-layers-per-virtual-pipeline-stage 2 --microbatch-group-size-per-virtual-pipeline-stage 4 --no-scatter-gather-tensors-in-pipeline
run_case pp4_vpp4_grad_noalign --tensor-model-parallel-size 2 --pipeline-model-parallel-size 4 --num-layers-per-virtual-pipeline-stage 2 --microbatch-group-size-per-virtual-pipeline-stage 4 --overlap-grad-reduce --ddp-num-buckets 4 --no-align-grad-reduce
run_case pp4_vpp4_grad_param_noalign --tensor-model-parallel-size 2 --pipeline-model-parallel-size 4 --num-layers-per-virtual-pipeline-stage 2 --microbatch-group-size-per-virtual-pipeline-stage 4 --overlap-grad-reduce --ddp-num-buckets 4 --overlap-param-gather --no-align-grad-reduce --no-align-param-gather
# PP8/TP1 high-P2P regime.
run_case pp8_vpp4_base --tensor-model-parallel-size 1 --pipeline-model-parallel-size 8 --num-layers-per-virtual-pipeline-stage 1 --microbatch-group-size-per-virtual-pipeline-stage 8
run_case pp8_vpp4_delay_wgrad --tensor-model-parallel-size 1 --pipeline-model-parallel-size 8 --num-layers-per-virtual-pipeline-stage 1 --microbatch-group-size-per-virtual-pipeline-stage 8 --delay-wgrad-compute
run_case pp8_vpp4_nosg --tensor-model-parallel-size 1 --pipeline-model-parallel-size 8 --num-layers-per-virtual-pipeline-stage 1 --microbatch-group-size-per-virtual-pipeline-stage 8 --no-scatter-gather-tensors-in-pipeline
run_case pp8_vpp4_warmup_flush --tensor-model-parallel-size 1 --pipeline-model-parallel-size 8 --num-layers-per-virtual-pipeline-stage 1 --microbatch-group-size-per-virtual-pipeline-stage 8 --overlap-p2p-communication-warmup-flush
run_case pp8_vpp4_ring_exchange --tensor-model-parallel-size 1 --pipeline-model-parallel-size 8 --num-layers-per-virtual-pipeline-stage 1 --microbatch-group-size-per-virtual-pipeline-stage 8 --use-ring-exchange-p2p
{ echo root="$ROOT"; cat "$ROOT/status.tsv"; for f in "$ROOT"/*/steady.tsv; do [ -s "$f" ] || continue; printf '%s ' "$(basename "$(dirname "$f")")"; grep 'elapsed time' "$f" | sed -n 's/.*elapsed time per iteration (ms): \([0-9.]*\).*/\1/p' | tail -15 | sort -n | awk '{a[NR]=$1;s+=$1} END{if(NR)printf "n=%d mean=%.2f med=%.2f p90=%.2f\n",NR,s/NR,a[int((NR+1)/2)],a[int(NR*.9)]}'; done; } > "$ROOT/summary.txt"
printf 'experiments_done=%s\n' "$(date -u +%Y-%m-%dT%H:%M:%SZ)" > "$ROOT/done.txt"; sleep "${HOLD_SECONDS:-50000}"
